import 'package:flutter/material.dart';
import '../../../core/navigation/app_routes.dart';
import '../../../core/theme/theme.dart';
import '../widgets/dashboard_list_components.dart';

class _User { final String name, email, created, type; bool active; _User(this.name, this.email, this.created, this.type, this.active); }
class DashboardUsersView extends StatefulWidget { const DashboardUsersView({super.key}); @override State<DashboardUsersView> createState() => _DashboardUsersViewState(); }
class _DashboardUsersViewState extends State<DashboardUsersView> {
  final _search = TextEditingController(); String _query = '', _type = 'Todos', _status = 'Todos';
  final _users = [_User('Daniel Lima','daniel@educano.com','12/01/2026','Administrador',true), _User('Ana Souza','ana@educano.com','28/02/2026','Aluno',true), _User('Marcos Silva','marcos@educano.com','04/03/2026','Professor',false)];
  @override void dispose() { _search.dispose(); super.dispose(); }
  List<_User> get _filtered => _users.where((u) => (_query.isEmpty || u.name.toLowerCase().contains(_query.toLowerCase()) || u.email.toLowerCase().contains(_query.toLowerCase())) && (_type == 'Todos' || u.type == _type) && (_status == 'Todos' || (_status == 'Ativos') == u.active)).toList();
  Future<void> _addUser() async { final result = await showDialog<_User>(context: context, builder: (_) => const _UserDialog()); if (result != null && mounted) setState(() => _users.add(result)); }
  Widget _filters() => LayoutBuilder(builder: (context, constraints) { final search = TextField(controller: _search, onChanged: (v) => setState(() => _query = v), decoration: const InputDecoration(hintText: 'Buscar por nome ou email...', prefixIcon: Icon(Icons.search_rounded))); final type = DropdownButtonFormField<String>(initialValue: _type, decoration: const InputDecoration(labelText: 'Tipo'), items: ['Todos', 'Aluno', 'Professor', 'Administrador'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => setState(() => _type = v!)); final status = DropdownButtonFormField<String>(initialValue: _status, decoration: const InputDecoration(labelText: 'Status'), items: ['Todos', 'Ativos', 'Inativos'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => setState(() => _status = v!)); if (constraints.maxWidth < 700) return Column(children: [search, const SizedBox(height: 16), Row(children: [Expanded(child: type), const SizedBox(width: 16), Expanded(child: status)])]); return Row(children: [Expanded(child: search), const SizedBox(width: 16), SizedBox(width: 170, child: type), const SizedBox(width: 16), SizedBox(width: 170, child: status)]); });
  @override Widget build(BuildContext context) => SingleChildScrollView(padding: const EdgeInsets.all(24), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Usuarios', style: Theme.of(context).textTheme.headlineMedium), const SizedBox(height: 8), Text('Gerencie as contas dos usuarios.', style: Theme.of(context).textTheme.bodyLarge), const SizedBox(height: 24), ElevatedButton.icon(onPressed: _addUser, icon: const Icon(Icons.add_rounded), label: const Text('Novo Usuario')), const SizedBox(height: 16), _filters(), const SizedBox(height: 24), DashboardListCard(title: 'Lista de Usuarios', count: _filtered.length, children: _filtered.map((u) => DashboardListRow(onTap: () => Navigator.pushNamed(context, AppRoutes.profile), leading: CircleAvatar(backgroundColor: EducanoColors.primaryBlue.withValues(alpha: .12), child: const Icon(Icons.person, color: EducanoColors.primaryBlue)), title: u.name, subtitle: '${u.email}  •  ${u.type}  •  Criado em ${u.created}', trailing: Switch(value: u.active, onChanged: (v) => setState(() => u.active = v)))).toList())]));
}

class _UserDialog extends StatefulWidget { const _UserDialog(); @override State<_UserDialog> createState() => _UserDialogState(); }
class _UserDialogState extends State<_UserDialog> {
  final _form = GlobalKey<FormState>(); final _name = TextEditingController(), _email = TextEditingController(), _password = TextEditingController(); String _type = 'Aluno', _course = 'Matematica Basica';
  @override void dispose() { _name.dispose(); _email.dispose(); _password.dispose(); super.dispose(); }
  @override Widget build(BuildContext context) => AlertDialog(title: const Text('Cadastrar usuario'), content: SizedBox(width: 420, child: Form(key: _form, child: Column(mainAxisSize: MainAxisSize.min, children: [TextFormField(controller: _name, decoration: const InputDecoration(labelText: 'Nome'), validator: (v) => (v ?? '').trim().isEmpty ? 'Informe o nome' : null), TextFormField(controller: _email, decoration: const InputDecoration(labelText: 'Email'), validator: (v) => (v ?? '').contains('@') ? null : 'Informe um email valido'), TextFormField(controller: _password, obscureText: true, decoration: const InputDecoration(labelText: 'Senha'), validator: (v) => (v ?? '').length < 6 ? 'Use ao menos 6 caracteres' : null), DropdownButtonFormField<String>(initialValue: _type, decoration: const InputDecoration(labelText: 'Tipo'), items: ['Aluno', 'Professor', 'Administrador'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => setState(() => _type = v!)), if (_type == 'Professor') DropdownButtonFormField<String>(initialValue: _course, decoration: const InputDecoration(labelText: 'Curso vinculado'), items: ['Matematica Basica', 'Portugues Avancado', 'Biologia Celular'].map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: (v) => setState(() => _course = v!))]))), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancelar')), ElevatedButton(onPressed: () { if (!_form.currentState!.validate()) return; Navigator.pop(context, _User(_name.text.trim(), _email.text.trim(), '08/10/2026', _type, true)); }, child: const Text('Cadastrar'))]);
}

Future<void> showDashboardUserDialog(BuildContext context) async {
  await showDialog<_User>(context: context, builder: (_) => const _UserDialog());
}
